head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL55300N";
scwin.xmlhttp = undefined;
scwin.w = '375';
scwin.h = '220';
scwin.indCodeWin = null;
scwin.instCodeWin = null;
scwin.l = undefined;
scwin.t = undefined;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — modifyYn, pubofrWrtYn

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "__rb0", attr: "label", fn: function () { return String(dma_basicComInfo.get("comNm")) + "(" + String(dma_basicComInfo.get("isurCd")) + ")"; } },
        { childId: "__rb1", attr: "label", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["usrId"] ?? "") + "/" + String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["corpUsrNm"] ?? ""); } },
        { childId: "__rb2", attr: "label", fn: function () { return String(dma_basicComInfo.get("mktTpNm")); } },
        { childId: "__rb3", attr: "label", fn: function () { return String(dma_basicComInfo.get("secugrpNm")); } },
        { childId: "txa_majshrhdContn", attr: "label", fn: function () { return String(dma_newListApplContn.get("majshrhdContn")); } },
        { childId: "txa_remk", attr: "label", fn: function () { return String(dma_newListApplContn.get("remk")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "ipt_isurCd", fn: function(){ return ((String(((dma_newListApplContn.get("isurCd") ?? (() => { throw new Error("unresolved:" + "newListApplContn.isurCd"); })())) == null ? '' : ((dma_newListApplContn.get("isurCd") ?? (() => { throw new Error("unresolved:" + "newListApplContn.isurCd"); })()))).length === 0)); } }, { id: "ipt_isurCd_2", fn: function(){ return (!(String(((dma_newListApplContn.get("isurCd") ?? (() => { throw new Error("unresolved:" + "newListApplContn.isurCd"); })())) == null ? '' : ((dma_newListApplContn.get("isurCd") ?? (() => { throw new Error("unresolved:" + "newListApplContn.isurCd"); })()))).length === 0)); } }, { id: "c_when_229_txt", fn: function(){ return ((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })()) === 0); } }, { id: "c_otherwise_230", fn: function(){ return (!(((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })()) === 0))); } }, { id: "c_when_291_txt", fn: function(){ return ((String(((dma_newListApplContn.get("crwfndRecmndInstNm") ?? (() => { throw new Error("unresolved:" + "newListApplContn.crwfndRecmndInstNm"); })())) == null ? '' : ((dma_newListApplContn.get("crwfndRecmndInstNm") ?? (() => { throw new Error("unresolved:" + "newListApplContn.crwfndRecmndInstNm"); })()))).length === 0)); } }, { id: "c_otherwise_292", fn: function(){ return (!(((String(((dma_newListApplContn.get("crwfndRecmndInstNm") ?? (() => { throw new Error("unresolved:" + "newListApplContn.crwfndRecmndInstNm"); })())) == null ? '' : ((dma_newListApplContn.get("crwfndRecmndInstNm") ?? (() => { throw new Error("unresolved:" + "newListApplContn.crwfndRecmndInstNm"); })()))).length === 0)))); } }, { id: "btn_register", fn: function(){ return ((dma_pageContext.get("modifyYn") ?? "")=== 'Y' && (dma_pageContext.get("pubofrWrtYn") ?? "")!== 'N'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_227", entity: "dlt_leadCom", countIds: [], cells: [{ childId: "__rc5", fn: function (v, i) { return String(v("name")); } }, { childId: "__rc6", fn: function (v, i) { return ", " + String(v("name")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_process", fn: function () { return String(String((dma_pageContext.get("process") ?? ""))); } },
        { childId: "ipt_isurCd", fn: function () { return String((dma_pageContext.get("isurCd") ?? "")); } },
        { childId: "ipt_corpRegNo1", fn: function () { return String(String(dma_newListApplContn.get("corpRegNo")).substring(0, 6)); } },
        { childId: "ipt_corpRegNo2", fn: function () { return String(String(dma_newListApplContn.get("corpRegNo")).substring(6, 13)); } },
        { childId: "ipt_bzRegNo1", fn: function () { return String(String(dma_newListApplContn.get("bzRegNo")).substring(0, 3)); } },
        { childId: "ipt_bzRegNo2", fn: function () { return String(String(dma_newListApplContn.get("bzRegNo")).substring(3, 5)); } },
        { childId: "ipt_bzRegNo3", fn: function () { return String(String(dma_newListApplContn.get("bzRegNo")).substring(5, 10)); } },
        { childId: "__rb4", fn: function () { return " " + String(dma_newListApplContn.get("leadcomMbrNm")) + " " + String(dma_newListApplContn.get("speclListTpNm")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const majshrhdContn = $c.util.getComponent("dma_registerReq").get("majshrhdContn");
        scwin.setLength(majshrhdContn, 'tdMajshrhdContn', '500');
        const remk = $c.util.getComponent("dma_registerReq").get("remk");
        scwin.setLength(remk, 'tdRemk', '2000');

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil55300n.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 2건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId","corpUsrNm"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil55300n' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(newlistapplcontn vs >-) — 어느 쪽인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.l =screen.width/2 - scwin.w/2; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil55300n' }); }

try { scwin.t =screen.height/2 - scwin.h/2; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil55300n' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_sessionFill();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil55300n.onpageload' });
    }
};

