/**
 * @method
 * @name checkListDd
 * @description check List Dd 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkListDd = async function () {

    scwin.xmlhttp = scwin.GetXmlHttpObject();

    if (scwin.xmlhttp == null) {
        await $c.win.alert ("Ajax를 지원하지 않는 브라우저입니다.\n 헬프데스크에 문의하시기 바랍니다!");
        return;
    }

    const frm = $c.util.getComponent('NewListApplContForm');
    const listSchdlDd = $c.util.getComponent('cal_listSchdlDd').getValue();
    if(($c.util.getComponent('cal_listSchdlDd').getValue() == null ? '' : String($c.util.getComponent('cal_listSchdlDd').getValue())) === ''){
        await $c.win.alert('상장(희망)일을 입력하십시오');
        return;
    }

    // KBoY 2014-12-03 SrM-000090012 201412만 중복 신청 가능.
    if(is201412(listSchdlDd)){
        await $c.win.alert('신청 가능한 희망일입니다.');
        $c.util.getComponent("dma_registerReq").set("possibleYn", 'Y');
    }else{
        const url="/ui/jsp/JLDFIL55300.xml?method=checkListDd&listSchdlDd=" + listSchdlDd + "&bzProcsNo="+"" + dma_pageContext.get("bzProcsNo") + "";
        scwin.xmlhttp.onreadystatechange=scwin.stateChanged;
        scwin.xmlhttp.open("POST",url,true);
        scwin.xmlhttp.send(null);
    }

};

/**
 * @method
 * @name stateChanged
 * @description state Changed 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.stateChanged = async function () {
    const frm = $c.util.getComponent('NewListApplContForm');
    if (scwin.xmlhttp.readyState === 4) {
        const returnText = scwin.trim(scwin.xmlhttp.responseText);
        if (returnText === 'N') {
            await $c.win.alert('이미 신청중인 상장(희망)일입니다.\n 다른 날짜를 선택해 주십시오.');
            $c.util.getComponent("cal_listSchdlDd").setValue('');
        } else {
            await $c.win.alert('신청 가능한 예정일입니다.');
            $c.util.getComponent("dma_registerReq").set("possibleYn", 'Y');
        }
    }
};

/**
 * @method
 * @name checkIsurSymbl
 * @description check Isur Symbl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkIsurSymbl = async function () {
    scwin.xmlhttp = scwin.GetXmlHttpObject();
    if (scwin.xmlhttp == null) {
        await $c.win.alert("Ajax를 지원하지 않는 브라우저입니다.\n 헬프데스크에 문의하시기 바랍니다!");
        return;
    }
    const frm = $c.util.getComponent('NewListApplContForm');
    const isurSymbl = $c.util.getComponent('ipt_isurSymbl').getValue();
    if (($c.util.getComponent('ipt_isurSymbl').getValue() == null ? '' : String($c.util.getComponent('ipt_isurSymbl').getValue())) === '') {
        return;
    }
    if ($c.util.getComponent('ipt_isurSymbl').getValue()=== $c.util.getComponent('ipt_isurSymbl').getValue()) {
        return;
    }
    if ($c.util.getComponent('ipt_isurSymbl').getValue().length > 6) {
        await $c.win.alert('6자리 이내 영문자만 입력할 수 있습니다');
        $c.util.getComponent('ipt_isurSymbl').select();
        return;
    }
    const url = "/ui/jsp/JLDFIL55300.xml?method=checkSymbl&symbl=" + isurSymbl + "&symblGubun=1";
    scwin.xmlhttp.onreadystatechange = scwin.stateChanged1;
    scwin.xmlhttp.open("POST", url, true);
    scwin.xmlhttp.send(null);
};

/**
 * @method
 * @name stateChanged1
 * @description state Changed1 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.stateChanged1 = async function () {
    const frm = $c.util.getComponent('NewListApplContForm');
    if (scwin.xmlhttp.readyState === 4) {
        const returnText = scwin.trim(scwin.xmlhttp.responseText);
        if (returnText === 'N') {
            await $c.win.alert('이미 사용중인 영문회사심볼입니다.\n 다른 심볼을 입력해 주십시오.');
            $c.util.getComponent('ipt_isurSymbl').select();
        } else {
            await $c.win.alert('신청 가능한 심볼입니다.');
        }
    }
    return;
};

/**
 * @method
 * @name GetXmlHttpObject
 * @description Get Xml Http Object 처리
 * @returns {void}
 * @hidden N
 */
scwin.GetXmlHttpObject = function () {
    if (XMLHttpRequest) {
        return new XMLHttpRequest();
    }

    return null;
};

/**
 * @method
 * @name calBytes
 * @description cal Bytes 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.calBytes = function (str) {
    let tcount = 0;
    const tmpStr = new String(str);
    const temp = tmpStr.length;
    let onechar;
    for (let k = 0; k < temp; k++) {
        onechar = tmpStr.charAt(k);
        if (escape(onechar).length > 4) {
            tcount += 2;
        } else {
            if (escape(onechar) === '%0A') {
                tcount += 2;
            } else {
                tcount += 1;
            }
        }
    }
    return tcount;
};

