/**
 * @method
 * @name checkBzRegNo
 * @description check Bz Reg No 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkBzRegNo = async function () {
    const bzRegNo1 = $c.util.getComponent("dma_registerReq").get("bzRegNo1");
    const bzRegNo2 = $c.util.getComponent("dma_registerReq").get("bzRegNo2");
    const bzRegNo3 = $c.util.getComponent("dma_registerReq").get("bzRegNo3");
    if (bzRegNo1 === '') {
        await $c.win.alert('사업자등록번호가 입력되지 않았습니다');
        (document.NewListApplContForm || { elements: [] }).bzRegNo1.select();
        return false;
    }
    if (bzRegNo2 === '') {
        await $c.win.alert('사업자등록번호가 입력되지 않았습니다');
        (document.NewListApplContForm || { elements: [] }).bzRegNo2.select();
        return false;
    }
    if (bzRegNo3 === '') {
        await $c.win.alert('사업자등록번호가 입력되지 않았습니다');
        (document.NewListApplContForm || { elements: [] }).bzRegNo3.select();
        return false;
    }
    const bzRegNo = bzRegNo1 + bzRegNo2 + bzRegNo3;
    if (bzRegNo.length !== 10) {
        await $c.win.alert("사업자등록번호가 잘못되었습니다.");
        return false;
    }
    let subMode = 0;
    subMode += parseInt(bzRegNo.substring(0, 1));
    subMode += parseInt(bzRegNo.substring(1, 2)) * 3 % 10;
    subMode += parseInt(bzRegNo.substring(2, 3)) * 7 % 10;
    subMode += parseInt(bzRegNo.substring(3, 4)) * 1 % 10;
    subMode += parseInt(bzRegNo.substring(4, 5)) * 3 % 10;
    subMode += parseInt(bzRegNo.substring(5, 6)) * 7 % 10;
    subMode += parseInt(bzRegNo.substring(6, 7)) * 1 % 10;
    subMode += parseInt(bzRegNo.substring(7, 8)) * 3 % 10;
    subMode += Math.floor(parseInt(bzRegNo.substring(8, 9)) * 5 / 10);
    subMode += parseInt(bzRegNo.substring(8, 9)) * 5 % 10;
    subMode += parseInt(bzRegNo.substring(9, 10));
    if (subMode % 10 !== 0) {
        await $c.win.alert("사업자등록번호가 잘못되었습니다.");
        return false;
    }
    $c.util.getComponent("dma_registerReq").set("bzRegNo", bzRegNo);
    return true;
};

/**
 * @method
 * @name checkCorpRegNo
 * @description check Corp Reg No 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkCorpRegNo = async function () {
    const corpRegNo1 = $c.util.getComponent("dma_registerReq").get("corpRegNo1");
    const corpRegNo2 = $c.util.getComponent("dma_registerReq").get("corpRegNo2");
    const corpRegNo = corpRegNo1 + corpRegNo2;
    if (corpRegNo1 === '') {
        await $c.win.alert('법인등록번호가 입력되지 않았습니다');
        (document.NewListApplContForm || { elements: [] }).corpRegNo1.select();
        return false;
    }
    if (corpRegNo2 === '') {
        await $c.win.alert('법인등록번호가 입력되지 않았습니다');
        (document.NewListApplContForm || { elements: [] }).corpRegNo2.select();
        return false;
    }
    if (isNaN(corpRegNo)) {
        await $c.win.alert('법인등록번호는 숫자만 입력하세요');
        return false;
    }
    if (corpRegNo.length !== 13) {
        await $c.win.alert('법인등록번호가 잘못되었습니다');
        return false;
    }
    $c.util.getComponent("dma_registerReq").set("corpRegNo", corpRegNo);
    return true;
};

